import {backtest} from '../chapter-08/model.mjs';
export const VERSION='1.0.0',STORAGE_KEY='qf-studio-chapter-09-v1';
export const STEPS=[['start','Prepare an audit',15],['bias','Repair the claim',30],['trials','Retain every trial',35],['plan','Freeze your plan',40],['evaluate','Reveal and compare',35],['finish','Revise the conclusion',25]];
export const EVALUATION_ID='qf-synthetic-evaluation-2026-v1';
// Original deterministic teaching sequence; this is not sampled market history.
export const EVALUATION_DATA=[100,103,105,101,97,94,96,99,102,98,95,97,94,92,96,99].map((open,i)=>({date:`2026-02-${String(i+1).padStart(2,'0')}`,open,close:open+[1,-1,2,-2][i%4]}));
export const DEVELOPMENT_TRIALS=[{id:'dev-3-10',window:3,costBps:10,segment:'Chapter 8 development',status:'retain regardless of sign'},{id:'dev-3-30',window:3,costBps:30,segment:'Chapter 8 development',status:'predefined cost sensitivity; retain regardless of sign'}];
export const AUDIT=[{id:'future',question:'A signal uses Tuesday close and earns Monday-open to Tuesday-open return. Enter 1 retain; 2 repair to next eligible open.',answer:2,hint:'Tuesday close was unknown at both opens. Use the Chapter 8 next-open timeline.',critical:true},{id:'selection',question:'A report shows only the best of 20 tested windows. Enter number of trials the log must retain.',answer:20,hint:'Retain all 20, including zero or negative results. A holdout does not undo repeated peeking.',critical:true},{id:'survivors',question:'Only currently surviving funds appear in an old-universe test. Enter 1 disclose survivorship and recover point-in-time universe; 2 call the result representative.',answer:1,hint:'Closed funds cannot simply disappear. Until recovered, limit the claim.',critical:true},{id:'dates',question:'Strategy evaluated February; benchmark evaluated January. Enter 1 compare; 2 align the same entry and exit dates.',answer:2,hint:'A relative result requires matching investable periods.',critical:true},{id:'cost',question:'£1,000 buys once at 10 basis points per notional. Entry cost (£)?',answer:1,hint:'10 / 10,000 × £1,000 = £1. Also charge the exit and benchmark consistently.',critical:true},{id:'transfer',question:'New case: a researcher tries six seeds, reports only a winning seed and calls it an untouched holdout. How many trials must the log retain?',answer:6,hint:'All six; relabel this period as inspected. A new untouched dataset would be needed for a new confirmatory claim.',critical:true}];
export const freshState=()=>({version:VERSION,fields:{},plans:[],runs:[],attempts:[],done:{}});
const record=x=>x&&typeof x==='object'&&!Array.isArray(x);
export const signature=p=>JSON.stringify([p.question,p.prediction,p.rule,p.window,p.costBps,p.initial,p.segment,p.benchmark,p.sensitivity,p.stopping]);
export function makePlan(fields,version=1){if((fields.question||'').trim().length<30||(fields.prediction||'').trim().length<20)throw Error('State a testable question (30+ characters) and an outcome prediction (20+).');return {version,question:fields.question.trim(),prediction:fields.prediction.trim(),rule:'Close above trailing 3-close mean; trade next open; long or cash',window:3,costBps:10,initial:1000,segment:EVALUATION_ID,benchmark:'Buy and hold; same eligible opens and entry/exit costs',sensitivity:'One additional cost case: 30 bps; no window search',stopping:'Report both cases once; retain all runs and negative results; revisions exploratory'};}
export function currentPlan(s){try{const p=s.plans.at(-1);return p&&signature(p.plan)===signature(makePlan(s.fields,p.plan.version))?p:null;}catch{return null;}}
export function freeze(s){const plan=makePlan(s.fields,s.plans.length+1);const snapshot={plan,signature:signature(plan),time:new Date().toISOString(),previouslyRevealed:s.runs.length>0};s.plans.push(snapshot);delete s.done.evaluate;delete s.done.finish;return snapshot;}
export function maximumDrawdown(path){if(!Array.isArray(path)||!path.length||path.some(x=>typeof x!=='number'||!Number.isFinite(x)||x<=0))throw Error('Use a nonempty positive finite wealth path.');let peak=path[0],largest=0;for(const value of path){peak=Math.max(peak,value);largest=Math.max(largest,100*(1-value/peak));}return largest;}
export function riskEvidence(result){return {...result,strategyMaxDrawdown:maximumDrawdown([result.initial,...result.rows.map(r=>r.endWealth),result.finalWealth]),benchmarkMaxDrawdown:maximumDrawdown([result.initial,...result.rows.map(r=>r.benchmarkEnd),result.benchmarkFinal])};}
export function evaluate(s){const frozen=currentPlan(s);if(!frozen)throw Error('Freeze the current plan before revealing results.');const run={planVersion:frozen.plan.version,signature:frozen.signature,time:new Date().toISOString(),exploratory:frozen.previouslyRevealed||s.runs.some(r=>r.signature!==frozen.signature),base:riskEvidence(backtest(EVALUATION_DATA,{window:3,costBps:10,initial:1000})),sensitivity:riskEvidence(backtest(EVALUATION_DATA,{window:3,costBps:30,initial:1000}))};s.runs.push(run);return run;}
export function latestEvidence(s){const p=currentPlan(s),r=s.runs.at(-1);return p&&r&&r.signature===p.signature&&r.planVersion===p.plan.version?r:null;}
export function auditGrade(fields){return AUDIT.map(q=>({id:q.id,correct:String(fields[q.id]??'').trim()!==''&&Number.isFinite(Number(fields[q.id]))&&Number(fields[q.id])===q.answer}));}
export function completion(s){const run=latestEvidence(s);return {start:s.fields.setup==='yes',bias:auditGrade(s.fields).every(x=>x.correct)&&s.attempts.some(a=>AUDIT.every(q=>a.fields?.[q.id]===s.fields[q.id])&&auditGrade(a.fields).every(x=>x.correct))&&(s.fields.correction||'').trim().length>=60,trials:s.fields.trials==='yes'&&(s.fields.trialNote||'').trim().length>=50,plan:!!currentPlan(s),evaluate:!!run&&s.fields.hand!==''&&Number.isFinite(Number(s.fields.hand))&&Math.abs(Number(s.fields.hand)-run.base.rows[0].endWealth)<.011&&s.fields.integrity==='yes',finish:!!run&&auditGrade(s.fields).every(x=>x.correct)&&s.attempts.some(a=>AUDIT.every(q=>a.fields?.[q.id]===s.fields[q.id])&&auditGrade(a.fields).every(x=>x.correct))&&s.fields.trials==='yes'&&s.fields.integrity==='yes'&&String(s.fields.hand??'').trim()!==''&&Math.abs(Number(s.fields.hand)-run.base.rows[0].endWealth)<.011&&(s.fields.conclusion||'').trim().length>=80&&(s.fields.revision||'').trim().length>=50&&s.fields.selfReview==='yes'};}
export function restoreState(raw){try{const x=JSON.parse(raw);if(x.version!==VERSION||!record(x.fields)||Object.values(x.fields).some(v=>typeof v!=='string')||!Array.isArray(x.plans)||!Array.isArray(x.runs)||!Array.isArray(x.attempts))throw Error();const s={...freshState(),fields:x.fields,attempts:x.attempts.filter(a=>record(a)&&typeof a.time==='string'&&record(a.fields))};s.plans=x.plans.filter(p=>record(p.plan)&&Number.isInteger(p.plan.version)&&p.signature===signature(p.plan)&&p.plan.window===3&&p.plan.costBps===10&&p.plan.initial===1000&&p.plan.segment===EVALUATION_ID);s.runs=x.runs.flatMap(r=>{const p=s.plans.find(p=>p.plan.version===r.planVersion&&p.signature===r.signature);return p?[{...r,base:riskEvidence(backtest(EVALUATION_DATA,{window:3,costBps:10,initial:1000})),sensitivity:riskEvidence(backtest(EVALUATION_DATA,{window:3,costBps:30,initial:1000}))}]:[];});s.done=completion(s);return s;}catch{return freshState();}}
